xpath.script:
(function () {
    "use strict";
    var dateEl, dentistEl;
    function loadSlots() {
        var date = dateEl.value;
        var block = document.getElementById("bk_slot_block");
        var box = document.getElementById("bk_slots");
        var empty = document.getElementById("bk_slot_empty");
        document.getElementById("bk_slot_value").value = "";
        document.getElementById("bk_slot_dentist").value = "";
        if (!date) { block.style.display = "none"; return; }
        block.style.display = "";
        box.innerHTML = "";
        var loading = document.createElement("span");
        loading.className = "text-muted small";
        loading.textContent = "Loading times…";
        box.appendChild(loading);
        empty.style.display = "none";
        var params = new URLSearchParams({date: date});
        if (dentistEl.value) { params.append("dentist_id", dentistEl.value); }
        var url = "/dental/book/slots?" + params.toString();
        fetch(url).then(function (r) { return r.json(); }).then(function (data) {
            box.innerHTML = "";
            var slots = (data && data.slots) || [];
            if (!slots.length) { empty.style.display = ""; return; }
            slots.forEach(function (s) {
                var btn = document.createElement("button");
                btn.type = "button";
                btn.className = "btn btn-outline-primary btn-sm bk-slot";
                btn.textContent = s.label;
                btn.dataset.value = s.value;
                btn.dataset.dentist = s.dentist_id;
                btn.addEventListener("click", function () {
                    box.querySelectorAll(".bk-slot").forEach(function (b) {
                        b.classList.remove("btn-primary");
                        b.classList.add("btn-outline-primary");
                    });
                    btn.classList.remove("btn-outline-primary");
                    btn.classList.add("btn-primary");
                    document.getElementById("bk_slot_value").value = s.value;
                    document.getElementById("bk_slot_dentist").value = s.dentist_id;
                });
                box.appendChild(btn);
            });
        }).catch(function () {
            box.innerHTML = "";
            var err = document.createElement("span");
            err.className = "text-danger small";
            err.textContent = "Could not load times.";
            box.appendChild(err);
        });
    }
    document.addEventListener("DOMContentLoaded", function () {
        dateEl = document.getElementById("bk_date");
        dentistEl = document.getElementById("bk_dentist");
        if (!dateEl || !dentistEl) { return; }
        dateEl.addEventListener("change", loadSlots);
        dentistEl.addEventListener("change", loadSlots);
        var form = dateEl.closest("form");
        if (form) {
            form.addEventListener("submit", function (ev) {
                var block = document.getElementById("bk_slot_block");
                var val = document.getElementById("bk_slot_value").value;
                var visible = block && block.style.display !== "none";
                var hasSlots = document.querySelectorAll(".bk-slot").length > 0;
                if (visible && hasSlots && !val) {
                    ev.preventDefault();
                    alert("Please choose an available time.");
                }
            });
        }
    });
})();
